def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell's value can be collected at most once, even if both paths pass through it.
    """
    if N <= 0:
        return 0

    # Build grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Special case: single cell grid
    if N == 1:
        return grid[1][1]

    # DP arrays: dp_prev[i1][i2] holds max sum for step k-1
    dp_prev = [[-10**18] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over steps k = i + j, starting from 3 up to 2N
    for k in range(3, 2 * N + 1):
        dp_cur = [[-10**18] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = -10**18
                # Consider four possible previous positions
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        val = dp_prev[pi1][pi2]
                        if val > best:
                            best = val
                if best == -10**18:
                    continue
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_cur[i1][i2] = best + add
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != -10**18 else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1.")
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        # Determine variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''
        term = f"{sign}{coeff_str}{var_part}"
        terms.append(term)
    if not terms:
        return '0'
    return ''.join(terms)

