def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.

    Parameters:
    A (str): The initial string to be transformed.
    B (str): The target string to be achieved.
    rules (list of tuples): A list of transformation rules, where each rule is a tuple
                            containing the source substring (to be replaced) and the
                            target substring (to replace with).

    Returns:
    Union[int, str]: The minimum number of transformation steps if possible, otherwise "NO ANSWER!".
    """
    # Basic input validation
    try:
        if not isinstance(A, str) or not isinstance(B, str):
            raise ValueError("A and B must be strings.")
        if not isinstance(rules, list):
            raise ValueError("rules must be a list.")
        for rule in rules:
            if not (isinstance(rule, tuple) and len(rule) == 2):
                raise ValueError("Each rule must be a tuple of two elements.")
            if not (isinstance(rule[0], str) and isinstance(rule[1], str)):
                raise ValueError("Rule elements must be strings.")
    except Exception:
        return "NO ANSWER!"

    # If already equal
    if A == B:
        return 0

    from collections import deque

    max_depth = 10
    visited = set()
    queue = deque()
    queue.append((A, 0))
    visited.add(A)

    while queue:
        current, steps = queue.popleft()
        if steps >= max_depth:
            continue
        for src, tgt in rules:
            if src == "":
                continue  # avoid infinite loop
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each rule is represented
                                as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.
    """
    # Input validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise ValueError("Each rule must be a tuple of two elements")
        if not (isinstance(rule[0], int) and isinstance(rule[1], int)):
            raise ValueError("Rule elements must be integers")

    # If no rules, only the original number is reachable
    if not rules:
        return 1

    from collections import deque

    visited = set()
    queue = deque()

    visited.add(n)
    queue.append(n)

    # Preprocess rules into a dictionary for quick lookup
    rule_dict = {}
    for x, y in rules:
        rule_dict.setdefault(str(x), []).append(str(y))

    while queue:
        current = queue.popleft()
        s = str(current)
        for i, digit in enumerate(s):
            if digit in rule_dict:
                for new_digit in rule_dict[digit]:
                    new_number_str = s[:i] + new_digit + s[i+1:]
                    try:
                        new_number = int(new_number_str)
                    except ValueError:
                        continue  # skip invalid conversions
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine if a statement refers to a day of the week
    def is_day_statement(stmt: str) -> bool:
        stmt_lower = stmt.lower()
        for day in days_of_week:
            if day.lower() in stmt_lower:
                return True
        return False

    # Helper to evaluate truth value of a single statement
    def evaluate(stmt: str, speaker: str) -> bool:
        stmt_clean = stmt.strip().rstrip('.').lower()
        # "I am guilty." or "I am not guilty."
        if stmt_clean.startswith('i am guilty'):
            return speaker.upper() == scenario.upper()
        if stmt_clean.startswith('i am not guilty'):
            return speaker.upper() != scenario.upper()
        # "X is guilty." or "X is not guilty."
        if ' is guilty' in stmt_clean:
            subject = stmt_clean.split(' is guilty')[0].strip()
            return subject.upper() == scenario.upper()
        if ' is not guilty' in stmt_clean:
            subject = stmt_clean.split(' is not guilty')[0].strip()
            return subject.upper() != scenario.upper()
        # If statement cannot be parsed, treat as neutral (does not affect consistency)
        return True

    for participant, stmts in statements.items():
        for stmt in stmts:
            if is_day_statement(stmt):
                continue  # ignore day-of-week statements
            truth = evaluate(stmt, participant)
            if participant in liar_count:
                if truth:  # liars should not make true statements
                    return False
            else:
                if not truth:  # non-liars should not make false statements
                    return False
    return True

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where the goal is to maximize
    the total value of herbs picked without exceeding the time limit. Each herb can be picked
    at most once and has an associated time cost and value.

    Args:
    - T (int): The total time available for picking herbs.
    - M (int): The number of different herbs in the cave.
    - herbs (List[Tuple[int, int]]): A list of tuples, where each tuple contains two integers
      representing the time required to pick the herb and the herb's value, respectively.

    Returns:
    - int: The maximum total value of herbs that can be picked within the time limit.
    """
    try:
        # Basic input validation
        if not isinstance(T, int) or T < 0:
            raise ValueError("T must be a non‑negative integer")
        if not isinstance(M, int) or M < 0:
            raise ValueError("M must be a non‑negative integer")
        if not isinstance(herbs, list):
            raise ValueError("herbs must be a list of (time, value) tuples")

        # If the provided M does not match the list length, adjust M to the actual length
        if len(herbs) != M:
            M = len(herbs)

        # DP array where dp[t] is the maximum value achievable with exactly t time
        dp = [0] * (T + 1)

        for idx, (time, value) in enumerate(herbs):
            # Skip invalid entries
            if not isinstance(time, int) or not isinstance(value, int):
                continue
            if time < 0 or value < 0:
                continue
            # 0/1 knapsack update (iterate backwards to avoid reuse)
            for t in range(T, time - 1, -1):
                new_val = dp[t - time] + value
                if new_val > dp[t]:
                    dp[t] = new_val

        # The best value achievable within the time limit is the maximum over all dp[t]
        return max(dp)
    except Exception:
        # In case of any unexpected error, return 0 as a safe fallback
        return 0

def min_remaining_space(V: int, n: int, volumes: list) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    This function uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items. It then returns the difference between the box's total capacity
    and this maximum occupied volume, which is the minimum remaining space.

    Args:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (List[int]): A list of the volumes of the n items.

    Returns:
    - int: The minimum remaining space in the box after fitting the items.
    """
    try:
        if not isinstance(V, int) or V < 0:
            raise ValueError("Box capacity V must be a non-negative integer.")
        if not isinstance(n, int) or n < 0:
            raise ValueError("Number of items n must be a non-negative integer.")
        if not isinstance(volumes, list):
            raise ValueError("volumes must be a list of integers.")
        if len(volumes) != n:
            raise ValueError("Length of volumes list does not match n.")
        # Ensure all volumes are integers and non-negative
        for idx, vol in enumerate(volumes):
            if not isinstance(vol, int) or vol < 0:
                raise ValueError(f"Volume at index {idx} is not a non-negative integer.")
        # DP array to track achievable sums up to V
        dp = [False] * (V + 1)
        dp[0] = True
        for vol in volumes:
            # Skip volumes larger than V as they cannot contribute to a valid subset
            if vol > V:
                continue
            for cap in range(V, vol - 1, -1):
                if dp[cap - vol]:
                    dp[cap] = True
        # Find the maximum achievable sum <= V
        max_occupied = max(idx for idx, achievable in enumerate(dp) if achievable)
        return V - max_occupied
    except Exception as e:
        # Log the exception details if needed; for now, re-raise with a clear message
        raise RuntimeError(f"Error computing minimum remaining space: {e}") from e

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 1:
        return 0

    # Longest strictly increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest strictly decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
